//! Which coordination events are worth VOICING, and the batch selection over a log tail.
//!
//! Ported from `@/features/sounds/lib/notifyCues` (#3082, epic #3071 P4a) — the consumer side of the
//! Sounds pillar: map a fleet coordination event to the Signal-kit cue that announces it.
//!
//! ## Why the mapping moved
//!
//! It is a projection of `coord.log`, which this crate already parses, and the renderer was paying
//! for it in the most expensive possible way: `useNotificationSounds` polls at **1 Hz** and reached
//! the tail through `readCoordState`, which folds the WHOLE 1000-line window into coordination state
//! — every waiter, latch, brief and request — in order to read `lines.length` and slice the tail.
//! The fold's result was discarded on every tick. Here the same tick parses the NEW lines only.
//!
//! ## The cue ids are strings on purpose
//!
//! They name cues in `src-tauri/data/sounds/signal.json`, which the renderer looks up and plays. This
//! crate has no business knowing what a cue sounds like, and taking a dependency on the sound library
//! to name three constants would invert the layering for nothing.

pub use coord_event_cue::coord_event_cue;
pub use cues_for_lines::cues_for_lines;
pub use notify_tick::notify_tick;

use crate::coord::{parse_coord_line, CoordEvent};

/// One notification tick: how long the log is now, and what to sound for the lines past `seen`.
#[derive(Debug, Clone, PartialEq, Eq, Default, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NotifyTick {
    /// Lines currently in the read window — the caller's next `seen`.
    pub total: usize,
    /// Cues for `lines[seen..]`, deduped. Empty while baselining.
    pub cues: Vec<&'static str>,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn line(session: &str, event: &str, r: &str, detail: &str) -> String {
        format!("2026-01-01T00:00:00Z\t{session}\t{event}\t{r}\t{detail}")
    }

    /// The voiced set is SMALL and closed, and each of the three says something different.
    #[test]
    fn only_completions_failures_and_user_pauses_are_voiced() {
        let lines = vec![
            line("a", "landed", "#1", ""),
            line("a", "merged", "#2", ""),
            line("a", "failed", "#3", "broke"),
            line("a", "waiting", "", "confirm?"),
            line("a", "closed", "#4", ""),
            line("a", "ask", "", "which one?"),
            line("a", "woke", "", ""),
        ];
        assert_eq!(cues_for_lines(&lines), vec!["success", "error", "notify"]);
    }

    /// A burst of merges in ONE tick must not stack identical cues.
    #[test]
    fn identical_cues_within_a_tick_collapse_to_one() {
        let lines: Vec<String> = (1..=5).map(|n| line("a", "merged", &format!("#{n}"), "")).collect();
        assert_eq!(cues_for_lines(&lines), vec!["success"]);
    }

    /// Garbage is dropped, not voiced and not fatal — the log is appended to by shell emitters.
    #[test]
    fn unparseable_lines_are_dropped_rather_than_voiced() {
        let lines = vec!["".to_string(), "not a coord line".to_string(), "\t\t\t".to_string()];
        assert!(cues_for_lines(&lines).is_empty());
    }

    /// NEVER VOICE THE BACKLOG. A fresh baseline is silent, and so is a log that shrank — otherwise
    /// enabling the setting mid-session replays every landing of the day at once.
    #[test]
    fn a_fresh_baseline_and_a_shrunk_log_both_stay_silent() {
        let lines = vec![line("a", "landed", "#1", ""), line("a", "failed", "#2", "x")];
        let fresh = notify_tick(&lines, -1);
        assert_eq!(fresh.total, 2);
        assert!(fresh.cues.is_empty(), "a first read only baselines");

        // The caller had seen more lines than exist ⇒ the log was rotated or replaced.
        let shrunk = notify_tick(&lines, 9);
        assert_eq!(shrunk.total, 2);
        assert!(shrunk.cues.is_empty(), "a shrunk log re-baselines rather than replaying");
    }

    /// Past the baseline, only the NEW lines sound.
    #[test]
    fn only_lines_past_the_baseline_sound() {
        let lines = vec![line("a", "landed", "#1", ""), line("a", "failed", "#2", "x")];
        assert_eq!(notify_tick(&lines, 1).cues, vec!["error"], "the landed line is already accounted for");
        assert_eq!(notify_tick(&lines, 0).cues, vec!["success", "error"]);
        assert!(notify_tick(&lines, 2).cues.is_empty(), "caught up ⇒ nothing new");
    }
}
